Ltac fix_sb1 :=
  lazymatch goal with
  | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ (Z_to_le_bytes 1 ?c)) _) => change (Z_to_le_bytes 1 c) with [Z_to_bv 8 c]
  | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ (le1 (Z_to_bv 64 ?v))) _) =>
    change (le1 (Z_to_bv 64 v)) with [Z_to_bv 8 (bv_unsigned (Z_to_bv 64 v))]; rewrite (unsigned_small64 v) by lia
  end.

(* [comment removed for export] *)
Lemma snwrite_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo fa B0 k dst nrem ck : Z) (ibuf obuf flags : list byte)
   (rpos rend wend wfn bsz mode lockv lbf : word) (J : fjunk),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> (lo + 64 <= bv_unsigned sp)%Z -> (bv_unsigned ra mod 2 = 0)%Z ->
  a0 = Z_to_bv 64 fa -> a1 = Z_to_bv 64 0 -> a2 = Z_to_bv 64 0 ->
  rw_cells rsegs m fa (fileC flags rpos rend wend (Z_to_bv 64 (B0 + k)) (Z_to_bv 64 B0) wfn (Z_to_bv 64 B0) bsz mode lockv lbf (Z_to_bv 64 ck) J) ->
  rw_cells rsegs m ck [C8 (Z_to_bv 64 dst); C8 (Z_to_bv 64 nrem)] ->
  u8arr rsegs m B0 ibuf -> u8arr rsegs m dst obuf ->
  (1 <= k <= nrem)%Z -> (k <= Z.of_nat (length ibuf))%Z -> (k + 1 <= Z.of_nat (length obuf))%Z -> (nrem < 2 ^ 62)%Z ->
  (0 < B0)%Z -> (B0 + Z.of_nat (length ibuf) < 2 ^ 63)%Z -> (0 < dst)%Z -> (dst + Z.of_nat (length obuf) < 2 ^ 63)%Z -> (fa + 232 < 2 ^ 63)%Z -> (ck + 16 < 2 ^ 63)%Z ->
  (bv_unsigned sp <= fa)%Z -> (bv_unsigned sp <= ck)%Z -> (bv_unsigned sp <= B0)%Z -> (bv_unsigned sp <= dst)%Z ->
  (fa + 232 <= ck \/ ck + 16 <= fa)%Z -> (fa + 232 <= dst \/ dst + Z.of_nat (length obuf) <= fa)%Z ->
  (ck + 16 <= dst \/ dst + Z.of_nat (length obuf) <= ck)%Z -> (B0 + Z.of_nat (length ibuf) <= dst \/ dst + Z.of_nat (length obuf) <= B0)%Z ->
  (B0 + Z.of_nat (length ibuf) <= fa \/ fa + 232 <= B0)%Z -> (B0 + Z.of_nat (length ibuf) <= ck \/ ck + 16 <= B0)%Z ->
  evt rsegs (fun ms' => exists t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 0) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F
               (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 64, bv_unsigned sp); (fa + 40, fa + 64); (ck, ck + 16); (dst, dst + Z.of_nat (length obuf))]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' fa (fileC flags rpos rend wend (Z_to_bv 64 B0) (Z_to_bv 64 B0) wfn (Z_to_bv 64 B0) bsz mode lockv lbf (Z_to_bv 64 ck) J)
      /\ rw_cells rsegs m' ck [C8 (Z_to_bv 64 (dst + k)); C8 (Z_to_bv 64 (nrem - k))]
      /\ u8arr rsegs m' B0 ibuf
      /\ u8arr rsegs m' dst (upd_bytes obuf 0 (firstn (Z.to_nat k) ibuf ++ [Z_to_bv 8 0])))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
